# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Aldous", "Wren")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Aldous, Wren | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_first_name_breaks_ties(self):
        people = [make("Lane", "Zed"), make("Lane", "Amy")]
        rows = seating_rows(people, 5)
        line = "Row 1: Lane, Amy | Lane, Zed"
        self.assertEqual(rows, [line])

    def test_bad_seat_counts(self):
        people = [make("Lane", "Amy")]
        for count in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(people, count)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
